@Filter.Tendsto.atTop_mul_atTop₀ : ∀ {α : Type u_1} {β : Type u_2} [inst : Semiring α] [inst_1 : PartialOrder α]
  [IsOrderedRing α] {l : Filter β} {f g : β → α},
  Filter.Tendsto f l Filter.atTop → Filter.Tendsto g l Filter.atTop → Filter.Tendsto (fun x => f x * g x) l Filter.atTop
@Filter.Tendsto.atTop_mul_atTop : ∀ {α : Type u_1} {M : Type u_2} [inst : CommMonoid M] [inst_1 : Preorder M]
  [IsOrderedMonoid M] {l : Filter α} {f g : α → M},
  Filter.Tendsto f l Filter.atTop → Filter.Tendsto g l Filter.atTop → Filter.Tendsto (fun x => f x * g x) l Filter.atTop
@Filter.Tendsto.cesaro : ∀ {u : ℕ → ℝ} {l : ℝ},
  Filter.Tendsto u Filter.atTop (nhds l) →
    Filter.Tendsto (fun n => (↑n)⁻¹ * ∑ i ∈ Finset.range n, u i) Filter.atTop (nhds l)
@tendsto_const_div_atTop_nhds_zero_nat : ∀ {𝕜 : Type u_1} [inst : DivisionSemiring 𝕜] [inst_1 : CharZero 𝕜]
  [inst_2 : TopologicalSpace 𝕜] [ContinuousSMul ℚ≥0 𝕜] [ContinuousMul 𝕜] (C : 𝕜),
  Filter.Tendsto (fun n => C / ↑n) Filter.atTop (nhds 0)

